{
  "probability": 0.95,
  "range_low": 0.90,
  "range_high": 0.98,
  "summary": [
    "Anchor from central Mediterranean annual toll baseline; 2,000–2,500 deaths per year provides context for 900 by Apr.",
    "Early-2026 pace (~606 deaths by February) implies substantial additional fatalities through March–April.",
    "Weather hazards and undercounting push the risk higher, while SAR/policy changes could dampen risk; net effect remains uncertain.",
    "Calibration yields a Bayesian posterior of 95% with a plausible near-term range."
  ],
  "confidence": "high",
  "narrative": "The unusually fast start to 2026 in Mediterranean deaths makes 900 by end-April plausible, supported by the IOM Missing Migrants data. While there are data gaps and potential mitigating factors, the balance of factors points to a high probability, with some uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Using the central Mediterranean route annual death toll as baseline; historical totals around 2,000–2,500 per year, with early-2026 pace suggesting non-trivial chance of reaching 900 by April."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 pace exceeds long-run average",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by late February imply March–April could push total toward or beyond 900 if the pace persists."
      },
      {
        "factor": "Weather events increasing fatalities",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Severe weather increases crossing hazards and fatalities, contributing to higher risk."
      },
      {
        "factor": "Under-counting/reporting delays",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Incomplete counts suggest true toll may be higher, supporting higher probability."
      },
      {
        "factor": "SAR capacity/policy changes",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stricter controls and reduced rescue could lower deaths; countervailing evidence suggests limited effect in near term."
      }
    ],
    "synthesis_rationale": "Starting from a long-run baseline, the current high early-2026 pace and hazard factors pull probability upward; reporting gaps and SAR dynamics introduce uncertainty and a mild downward check. The posterior probability is 0.95 after calibrating with the observed pace and plausible countervailing factors"
  }
}

{
  "probability": 0.95,
  "range_low": 0.85,
  "range_high": 0.99,
  "summary": [
    "Early-2026 Mediterranean death pace is unusually high, with about 606 deaths reported through February 2026, making a run to 900 by end-April plausible.",
    "Weather-related hazards have amplified crossing risks, adding to the near-term fatality count.",
    "Underreporting and reporting lags suggest the true toll could be higher than observed so far, reinforcing the upside risk to the target.",
    "Policy/SAR capacity changes could dampen deaths somewhat, introducing a countervailing force that tempers the likelihood of hitting 900."
  ],
  "confidence": "high",
  "narrative": "Starting from a mid-to-high anchor on the Mediterranean toll trajectory, the observed rapid pace through February 2026 combined with ongoing hazard conditions supports a high likelihood of reaching 900 deaths by end-April, though data gaps and rescue dynamics inject some uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.85,
      "basis": "reference class anchor on IOM Missing Migrants Project Mediterranean route tolls; early-2026 pace suggests movement toward the 900-death threshold by end-April, justifying a high-but-not-assured baseline."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 pace exceeds long-run average",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Approximately 606 deaths by February 2026 indicate a pace well above typical monthly rates; if March–April maintain or exceed, 900 by end-April becomes plausible."
      },
      {
        "factor": "Weather events and shipwreck risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Severe weather in early 2026 has elevated crossing hazards, contributing to higher fatality potential in the near term."
      },
      {
        "factor": "Underreporting / data delays",
        "direction": "up",
        "magnitute": "moderate",
        "rationale": "IOM cautions that many incidents go unrecorded or are reported with delays, implying the true toll could exceed observed counts and push toward 900."
      },
      {
        "factor": "Policy/SAR capacity changes",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stricter controls and varying rescue capacity can reduce fatalities if rescues keep pace, offsetting some of the upward pressure from pace and hazards."
      }
    ],
    "synthesis_rationale": "The updates combine with a positive net signal (three upward updates and one downward update) starting from an 0.85 anchor. Treating updates as roughly additive on a log-odds style scale and acknowledging possible correlations (e.g., pace and underreporting) yields a posterior near 0.95. The calibration acknowledges the caveat that data lags and reporting gaps can both push the true toll higher and complicate precise tipping-point estimation."
  }
}

{
  "probability": 0.70,
  "range_low": 0.60,
  "range_high": 0.80,
  "summary": [
    "As of late February 2026, about 606 Mediterranean deaths/missing, indicating a record-start pace that could plausibly continue into March–April.",
    "Weather shocks and ongoing high hazard levels raise the risk of additional fatalities in the near term.",
    "Underreporting and reporting delays imply the true toll may be higher than observed counts, lifting the probability of reaching 900.",
    "Countervailing factors like SAR effectiveness or policy changes could dampen fatalities, but multiple drivers appear to push the total upward, keeping the 900 mark plausible but uncertain."
  ],
  "confidence": "medium",
  "narrative": "Starting from a mid-to-high anchor for annual Mediterranean deaths, the unusually fast early-2026 pace and persistent hazards make reaching 900 deaths by end-April plausible. However, data gaps and possible shifts in rescue capacity or policy introduce meaningful uncertainty around this near-term forecast.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Reference class is the IOM Missing Migrants Project Mediterranean death toll by calendar year. Historical annual tolls have been around 2,000–2,500, so 900 by end-April represents a substantial portion of a year. The anchor probability 0.65 reflects a balanced starting point given pace-to-date and typical year-to-year variability."
    },
    "factor_updates": [
      {
        "factor": "Surge in early-2026 Mediterranean deaths (high pace)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths/missing by late February; if March–April maintain pace, the cumulative toll could approach 900 by end-April."
      },
      {
        "factor": "Weather events and shipwreck risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Severe weather increases crossing hazards and can sustain elevated fatality counts."
      },
      {
        "factor": "Underreporting / data delays in Missing Migrants Project",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Unrecorded wrecks or delayed reporting imply the true toll may be higher than observed counts."
      },
      {
        "factor": "Impact of search-and-rescue (SAR) operations on death toll",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "More effective SAR could save lives, reducing deaths and lowering the probability of hitting 900."
      },
      {
        "factor": "Policy deterrence / changes in SAR capacity affecting crossing dynamics",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Stricter controls and disrupted rescue capacity can raise mortality risk by decreasing rescue likelihood."
      }
    ],
    "synthesis_rationale": "The forecast starts from a 0.65 anchor toward a high-but-contingent outcome. Upward forces come from pace, weather, underreporting, and deterrence effects, while SAR effectiveness provides a counterweight. Given the magnitude of the pace signal and potential reporting gaps, the net view tilts toward a non-negligible chance of reaching 900 by end-April, but substantial uncertainty remains due to data gaps and possible policy or operational shifts."
  }
}
